\begin{tikzpicture}
\begin{axis}[
    width=0.74\textwidth,
    height=0.46\textwidth,
    xmin=-4.4, xmax=5.2,
    ymin=-5, ymax=6,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-3,1,4},
    ytick={-4,-2,2,4},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-4.2:5.0, samples=160] {0.1*(x+3)*(x-1)*(x-4)};
\addplot[only marks, mark=*] coordinates {(-3,0) (1,0) (4,0)};
\end{axis}
\end{tikzpicture}

